import {useState} from 'react';import{createRoot}from'react-dom/client';import{AnchorRemovalDialog}from'../../src/components/AnchorRemovalDialog.tsx';import{AnchorMenuRow}from'../../src/components/AnchorMenuRow.tsx';
const anchor={realRoomId:77,roomIdInput:'77',uname:'很长的主播名称用于确认布局',lastConnectedAt:0};
function App(){const[open,setOpen]=useState(false),[removed,setRemoved]=useState(0);return <><AnchorMenuRow anchor={anchor} avatar={<span>头像</span>} onSelect={()=>{}} onRemove={()=>setOpen(true)}/>{['normal','blocked','failure','empty','cardFailure'].map(mode=><button onClick={()=>{(window as any).mode=mode;setOpen(true)}}>{mode}</button>)}<output>{removed}</output>{open&&<AnchorRemovalDialog anchor={anchor} onClose={()=>setOpen(false)} onRemove={async()=>{if((window as any).mode==='cardFailure'){(window as any).mode='normal';throw Error('保存失败')} (window as any).calls.push('card');setRemoved(n=>n+1)}}/>}</>};(window as any).calls=[];createRoot(document.getElementById('root')!).render(<App/>);
